```sql
SELECT T1.Fname
FROM Student AS T1
WHERE T1.StuID IN (
    SELECT StuID FROM Has_Pet AS HP JOIN Pets AS P ON HP.PetID = P.PetID WHERE P.PetType = 'Cat'
)
AND T1.StuID IN (
    SELECT StuID FROM Has_Pet AS HP JOIN Pets AS P ON HP.PetID = P.PetID WHERE P.PetType = 'Dog'
);
```
